<?php require_once __DIR__.'/../config/bootstrap.php';
if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['ok'=>false,'message'=>'Method not allowed'],405);$u=current_user();if(!$u)json_response(['ok'=>false,'message'=>'请先登录']);if($u['plan']!=='pro'&&trial_remaining($u)<=0)json_response(['ok'=>false,'message'=>'免费体验已结束，请开通会员']);$text=trim($_POST['text']??'');$source=$_POST['source']??'auto';$target=$_POST['target']??'en';if($text==='')json_response(['ok'=>false,'message'=>'请输入文本']);if(mb_strlen($text)>5000)json_response(['ok'=>false,'message'=>'单次最多 5000 字']);global $config;$translation='';$mode='demo';if($config['translation']['api_key']||$config['translation']['endpoint']){ $payload=['q'=>$text,'source'=>$source==='auto'?'auto':$source,'target'=>$target,'format'=>'text'];if($config['translation']['api_key'])$payload['api_key']=$config['translation']['api_key'];$ch=curl_init($config['translation']['endpoint']);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($payload),CURLOPT_TIMEOUT=>15,CURLOPT_HTTPHEADER=>['Accept: application/json']]);$raw=curl_exec($ch);$err=curl_error($ch);curl_close($ch);if(!$err&&$raw){$j=json_decode($raw,true);if(!empty($j['translatedText'])){$translation=$j['translatedText'];$mode='api';}}}
